from dataclasses import dataclass
import math
import numbers


@dataclass(frozen=True)
class Reading:
    imbalance: float
    value: float
    change_percent: float | None


def _number(value):
    if isinstance(value, bool) or not isinstance(value, numbers.Real):
        raise TypeError("numeric values must be real numbers")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("numeric values must be finite")
    return result


def collect_readings(snapshots, max_points, stop_imbalance):
    if isinstance(max_points, bool) or not isinstance(max_points, int):
        raise TypeError("max_points must be an integer")
    if max_points < 0:
        raise ValueError("max_points must be nonnegative")
    threshold = _number(stop_imbalance)
    if threshold < 0:
        raise ValueError("stop_imbalance must be nonnegative")
    if max_points == 0:
        return []

    result = []
    previous = None
    for snapshot in snapshots:
        if not isinstance(snapshot, dict) or set(snapshot) != {"offers", "requests", "value"}:
            raise TypeError("invalid snapshot")
        totals = []
        for key in ("offers", "requests"):
            side = snapshot[key]
            if not isinstance(side, list):
                raise TypeError("book sides must be lists")
            total = 0.0
            for row in side:
                if not isinstance(row, (list, tuple)) or len(row) != 2:
                    raise TypeError("book rows must contain level and quantity")
                _number(row[0])
                quantity = _number(row[1])
                if quantity < 0:
                    raise ValueError("quantities must be nonnegative")
                total += quantity
            totals.append(total)
        value = _number(snapshot["value"])
        imbalance = totals[1] - totals[0]
        if abs(imbalance) > threshold:
            break
        change = None if previous is None or previous == 0 else (value - previous) / abs(previous) * 100.0
        result.append(Reading(imbalance, value, change))
        previous = value
        if len(result) == max_points:
            break
    return result

